60	// Cartaz A4 pra fixar tipo poster no salão — QR grande, logo, nome e frase de chamada.
61	export const printCartazCardapioDigital = (qrUrl, nomeRestaurante, logoUrl) => {
62	  const html = `<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Cardápio Digital - ${nomeRestaurante ?? ''}</title>
63	<style>
64	*{margin:0;padding:0;box-sizing:border-box}
65	@page{size:A4;margin:0}
66	body{font-family:'Segoe UI',Arial,sans-serif;width:210mm;height:297mm;display:flex;flex-direction:column;align-items:center;justify-content:center;background:#fff;color:#18181B;padding:20mm}
67	.logo{max-width:120px;max-height:120px;object-fit:contain;margin-bottom:16px;border-radius:16px}
68	.nome{font-size:40px;font-weight:900;text-align:center;letter-spacing:-1px;margin-bottom:6px;word-break:break-word}
69	.badge{background:#FF441F;color:#fff;font-size:16px;font-weight:800;letter-spacing:3px;padding:8px 24px;border-radius:999px;text-transform:uppercase;margin-bottom:36px}
70	.qrbox{border:4px solid #18181B;border-radius:32px;padding:24px;margin-bottom:32px}
71	.qrbox img{display:block;width:340px;height:340px}
72	.frase{font-size:22px;font-weight:700;text-align:center;max-width:480px;color:#27272A;line-height:1.4}
73	.sub{font-size:15px;color:#71717A;margin-top:14px;text-align:center}
74	@media print{button{display:none!important}}
75	</style></head><body>
76	${logoUrl ? `<img class="logo" src="${logoUrl}" />` : ''}
77	<div class="nome">${nomeRestaurante ?? 'Nosso Restaurante'}</div>
78	<div class="badge">Cardápio Digital</div>
79	<div class="qrbox"><img src="${qrUrl}" width="340" height="340" alt="QR code cardápio" /></div>
80	<div class="frase">Escaneie e descubra sabores que valem a viagem até a mesa.</div>
81	<div class="sub">Aponte a câmera do celular para o QR code acima</div>
82	<script>
83	window.addEventListener('load', function(){
84	  window.print();
85	  setTimeout(function(){ try{ window.frameElement.parentNode.removeChild(window.frameElement) }catch(e){} }, 500);
86	});
87	</script>
88	</body></html>`;
89	
90	  const frameId = `cartaz-cardapio-frame-${Date.now()}`;
91	  const iframe = document.createElement('iframe');
92	  iframe.id = frameId;
93	  iframe.style.cssText = 'position:fixed;bottom:-1px;left:-1px;width:1px;height:1px;border:0;opacity:0;pointer-events:none';
94	  document.body.appendChild(iframe);
95	
96	  try {
97	    iframe.contentDocument.open();
98	    iframe.contentDocument.write(html);
99	    iframe.contentDocument.close();
100	  } catch {
101	    iframe.remove();
102	    const w = window.open('', '_blank');
103	    if (w) { w.document.write(html); w.document.close(); }
104	  }
105	};
