109	  const html = `<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Cardápio Digital</title>
110	<style>
111	*{margin:0;padding:0;box-sizing:border-box}
112	body{font-family:'Courier New',monospace;font-size:13px;padding:12px;color:#000;max-width:300px;margin:0 auto}
113	.center{text-align:center;display:block}
114	.logo{max-width:70px;max-height:70px;object-fit:contain;display:block;margin:0 auto 6px}
