121	</style></head><body>
122	${logoUrl ? `<img class="logo" src="${logoUrl}" />` : ''}
123	<div class="rest">${nomeRestaurante ?? 'RESTAURANTE'}</div>
124	<div class="badge">CARDÁPIO DIGITAL</div>
125	<hr/>
126	<img class="qr" src="${qrUrl}" width="180" height="180" alt="QR code cardápio" />
127	<div class="frase">Escaneie e confira nosso cardápio completo!</div>
128	<hr/>
129	<div class="center" style="font-size:10px;margin-top:4px">Obrigado pela visita</div>
130	<script>
131	window.addEventListener('load', function(){
