155	export const barcodeValue = (id) => String(id).padStart(8, '0');
156	
157	export const getPrinterName = () => localStorage.getItem('kitchen_printer_name') ?? '';
158	export const setPrinterName = (name) => localStorage.setItem('kitchen_printer_name', name);
159	
160	const showPrinterToast = (printerName) => {
161	  const existing = document.getElementById('printer-toast');
162	  if (existing) existing.remove();
163	  const toast = document.createElement('div');
164	  toast.id = 'printer-toast';
165	  toast.innerHTML = `🖨️ Selecione <strong>"${printerName}"</strong> na caixa de impressão`;
166	  toast.style.cssText = 'position:fixed;bottom:24px;left:50%;transform:translateX(-50%);background:#1A1A1A;color:#FFD700;padding:12px 22px;border-radius:14px;font-size:14px;font-weight:600;z-index:99999;box-shadow:0 4px 24px rgba(0,0,0,0.6);white-space:nowrap';
167	  document.body.appendChild(toast);
168	  setTimeout(() => toast.remove(), 5000);
169	};
170	
171	/**
172	 * Prints comanda using a hidden iframe (avoids popup blockers — works from setInterval/auto-print).
173	 * If printerHint (name) is set, shows a toast reminding which printer to select.
174	 */
175	export const printComanda = (pedido, itens, restauranteNome, printerHint) => {
176	  const hint = printerHint ?? getPrinterName();
177	  if (hint) showPrinterToast(hint);
178	
179	  const bc = barcodeValue(pedido.id);
180	  const hora = new Date(pedido.created_at).toLocaleString('pt-BR', { day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' });
181	  const clienteNome = pedido.customers?.name ?? (pedido.cliente?.name ?? '');
182	  const pgto = PAYMENT_LABELS[pedido.payment_method] ?? pedido.payment_method;
183	  const isCash = pedido.payment_method === 'cash';
184	
185	  const html = `<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Comanda #${pedido.id}</title>
186	<style>
187	*{margin:0;padding:0;box-sizing:border-box}
188	body{font-family:'Courier New',monospace;font-size:14px;padding:12px;color:#000;max-width:300px;margin:0 auto}
189	.center{text-align:center;display:block}
190	.big{font-size:30px;font-weight:900;text-align:center;letter-spacing:3px;margin:8px 0}
191	.rest{font-size:16px;font-weight:bold;text-align:center;margin-bottom:4px}
192	hr{border:none;border-top:1px dashed #000;margin:8px 0}
193	.item{display:flex;gap:8px;padding:3px 0;font-size:15px}
194	.qty{font-weight:900;min-width:28px}
195	.foot{font-size:11px;text-align:center;margin-top:6px}
196	#barcode{display:block;margin:8px auto 4px;max-width:260px}
197	@media print{button{display:none!important}}
198	</style></head><body>
199	<div class="rest">${restauranteNome ?? 'RESTAURANTE'}</div>
200	<div class="center" style="font-size:11px;letter-spacing:1px">COMANDA DE COZINHA</div>
201	<hr/>
202	<div class="big">PEDIDO #${pedido.id}</div>
203	<div class="center" style="font-size:13px">${hora}</div>
204	${clienteNome ? `<div class="center" style="font-size:12px;margin-top:2px;font-weight:bold">${clienteNome}</div>` : ''}
205	<hr/>
206	${itens.map((i) => `<div class="item"><span class="qty">${i.quantity}x</span><span>${i.product_name ?? `Produto #${i.product_id}`}</span></div>`).join('')}
207	<hr/>
208	<div class="center" style="font-size:13px">Pgto: <b>${pgto}</b>${isCash ? ' &nbsp;⚠ COBRAR' : ''}</div>
209	<hr/>
210	<svg id="barcode"></svg>
211	<div style="text-align:center;margin:6px 0 2px">
212	  <img src="https://api.qrserver.com/v1/create-qr-code/?size=110x110&data=${bc}&qzone=1" width="110" height="110" alt="QR #${pedido.id}" style="display:inline-block" />
213	  <div style="font-size:10px;letter-spacing:1px;margin-top:2px">SCAN MOTOBOY</div>
214	</div>
215	<div class="foot">Impresso: ${new Date().toLocaleString('pt-BR')}</div>
216	<script>
217	function doBarcode(){
218	  if(typeof JsBarcode!=='undefined'){
219	    JsBarcode("#barcode","${bc}",{format:"CODE128",width:2,height:56,displayValue:true,fontSize:13,text:"#${pedido.id}",margin:6,background:"#ffffff"});
220	  }
221	  window.print();
222	  try{window.frameElement.parentNode.removeChild(window.frameElement)}catch(e){}
223	}
224	var s=document.createElement('script');
225	s.src='https://cdn.jsdelivr.net/npm/jsbarcode@3.11.6/dist/JsBarcode.all.min.js';
226	s.onload=doBarcode;
227	s.onerror=function(){document.getElementById('barcode').style.display='none';doBarcode()};
228	document.head.appendChild(s);
229	</script>
230	</body></html>`;
231	
232	  // Use hidden iframe — no popup blocker, works from setInterval
233	  const frameId = `comanda-frame-${pedido.id}-${Date.now()}`;
234	  const iframe = document.createElement('iframe');
235	  iframe.id = frameId;
236	  iframe.style.cssText = 'position:fixed;bottom:-1px;left:-1px;width:1px;height:1px;border:0;opacity:0;pointer-events:none';
237	  document.body.appendChild(iframe);
238	
239	  try {
240	    iframe.contentDocument.open();
241	    iframe.contentDocument.write(html);
242	    iframe.contentDocument.close();
243	  } catch {
244	    // cross-origin fallback (shouldn't happen for same-origin but just in case)
245	    iframe.remove();
246	    const w = window.open('', '_blank', 'width=440,height=680');
247	    if (w) { w.document.write(html); w.document.close(); }
248	  }
249	};
