251	// Recibo do cliente — emitido pelo caixa no momento em que a comanda é paga (ideia 9 do
252	// módulo Salão: garçom só coleta a forma, quem emite o recibo de fato é o caixa).
253	export const printReciboCliente = (comanda, itens, valores, restauranteNome) => {
254	  const fmt = (v) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(v ?? 0);
255	  const { subtotal, desconto = 0, acrescimo = 0, gorjeta = 0, taxaCartao = 0, total, formaPagamento, trocoDado, pagamentos = [] } = valores;
256	  const PAGAMENTO_ORIGEM = { garcom: 'garçom', estabelecimento: 'caixa' };
257	  const mesa = comanda?.mesa_id ? `Mesa ${comanda.mesas?.numero ?? comanda.mesa_id}` : 'Comanda avulsa';
258	  const hora = new Date().toLocaleString('pt-BR');
259	
260	  const html = `<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Recibo</title>
261	<style>
262	*{margin:0;padding:0;box-sizing:border-box}
263	body{font-family:'Courier New',monospace;font-size:14px;padding:12px;color:#000;max-width:300px;margin:0 auto}
264	.center{text-align:center;display:block}
265	.rest{font-size:16px;font-weight:bold;text-align:center;margin-bottom:4px}
266	hr{border:none;border-top:1px dashed #000;margin:8px 0}
267	.item{display:flex;gap:6px;padding:3px 0;font-size:14px}
268	.item .col-qtd{flex-shrink:0;width:26px;font-weight:700}
269	.item .col-desc{flex:1;min-width:0;word-wrap:break-word}
270	.item .col-valor{flex-shrink:0;min-width:58px;text-align:right}
271	.linha{display:flex;justify-content:space-between;font-size:13px;padding:1px 0}
272	.total{display:flex;justify-content:space-between;font-size:18px;font-weight:900;padding:4px 0}
273	.foot{font-size:11px;text-align:center;margin-top:8px}
274	@media print{button{display:none!important}}
275	</style></head><body>
276	<div class="rest">${restauranteNome ?? 'RESTAURANTE'}</div>
277	<div class="center" style="font-size:11px;letter-spacing:1px">RECIBO DE PAGAMENTO</div>
278	<hr/>
279	<div class="center" style="font-size:13px;font-weight:bold">${mesa}</div>
280	${comanda?.cliente_mesa_nome ? `<div class="center" style="font-size:12px">${comanda.cliente_mesa_nome}</div>` : ''}
281	<div class="center" style="font-size:11px">${hora}</div>
282	<hr/>
283	${itens.map((i) => `<div class="item"><span class="col-qtd">${i.quantity}x</span><span class="col-desc">${i.product_name ?? i.products?.name}</span><span class="col-valor">${fmt(i.quantity * (i.unit_price ?? 0))}</span></div>`).join('')}
284	<hr/>
285	<div class="linha"><span>Subtotal</span><span>${fmt(subtotal)}</span></div>
286	${desconto > 0 ? `<div class="linha"><span>Desconto</span><span>- ${fmt(desconto)}</span></div>` : ''}
287	${acrescimo > 0 ? `<div class="linha"><span>Acréscimo</span><span>+ ${fmt(acrescimo)}</span></div>` : ''}
288	${gorjeta > 0 ? `<div class="linha"><span>Gorjeta</span><span>${fmt(gorjeta)}</span></div>` : ''}
289	${taxaCartao > 0 ? `<div class="linha"><span>Taxa cartão</span><span>+ ${fmt(taxaCartao)}</span></div>` : ''}
290	<hr/>
291	<div class="total"><span>TOTAL</span><span>${fmt(total)}</span></div>
292	${pagamentos.length > 0 ? `
293	<hr/>
294	<div class="center" style="font-size:11px;font-weight:bold">PAGAMENTOS</div>
295	${pagamentos.map((p) => `<div class="linha"><span>${PAYMENT_LABELS[p.forma_pagamento] ?? p.forma_pagamento} (${PAGAMENTO_ORIGEM[p.origem] ?? p.origem})${p.taxa_cartao_valor > 0 ? ` + taxa ${fmt(p.taxa_cartao_valor)}` : ''}</span><span>${fmt(p.valor + (p.taxa_cartao_valor || 0))}</span></div>`).join('')}
296	` : `
297	<div class="linha"><span>Forma de pagamento</span><span>${PAYMENT_LABELS[formaPagamento] ?? formaPagamento}</span></div>
298	`}
299	${trocoDado > 0 ? `<div class="linha"><span>Troco</span><span>${fmt(trocoDado)}</span></div>` : ''}
300	<hr/>
301	<div class="foot">Obrigado pela preferência!</div>
302	<script>
303	window.print();
304	try{window.frameElement.parentNode.removeChild(window.frameElement)}catch(e){}
305	</script>
306	</body></html>`;
307	
308	  const frameId = `recibo-frame-${Date.now()}`;
309	  const iframe = document.createElement('iframe');
310	  iframe.id = frameId;
311	  iframe.style.cssText = 'position:fixed;bottom:-1px;left:-1px;width:1px;height:1px;border:0;opacity:0;pointer-events:none';
312	  document.body.appendChild(iframe);
313	
314	  try {
315	    iframe.contentDocument.open();
316	    iframe.contentDocument.write(html);
317	    iframe.contentDocument.close();
318	  } catch {
319	    iframe.remove();
320	    const w = window.open('', '_blank', 'width=440,height=680');
321	    if (w) { w.document.write(html); w.document.close(); }
322	  }
323	};
324	
325	// Conferência pedida pelo caixa antes de fechar a conta — itens + subtotal e também
326	// a prévia de acréscimo/gorjeta/taxa/forma de pagamento já escolhidos na tela (ainda
327	// não é o recibo final, que só sai depois de pago via printReciboCliente).
328	export const printConferenciaComanda = (comanda, itens, valores = {}, restauranteNome) => {
329	  const fmt = (v) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(v ?? 0);
330	  const subtotal = itens.reduce((acc, i) => acc + i.quantity * (i.unit_price ?? i.products?.price ?? 0), 0);
331	  const { desconto = 0, acrescimo = 0, gorjeta = 0, taxaCartao = 0, formaPagamento, pagamentos = [] } = valores;
332	  const total = subtotal - desconto + acrescimo + gorjeta + taxaCartao;
333	  const mesa = comanda?.mesa_id ? `Mesa ${comanda.mesas?.numero ?? comanda.mesa_id}` : 'Comanda avulsa';
334	  const hora = new Date().toLocaleString('pt-BR');
335	  const PAGAMENTO_ORIGEM = { garcom: 'garçom', estabelecimento: 'caixa' };
336	
337	  const html = `<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Conferência</title>
338	<style>
339	*{margin:0;padding:0;box-sizing:border-box}
